119→type WidgetConfig = {
120→  position: string;
121→  primaryColor: string;
122→  successColor: string;
123→  errorColor: string;
124→  backgroundColor: string;
125→  textColor: string;
126→  heading: string;
127→  placeholder: string;
128→  buttonText: string;
129→  successMessage: string;
130→  errorMessage: string;
131→  notFoundMessage: string;
132→  showEta: boolean;
133→  showZone: boolean;
134→  showWaitlistOnFailure: boolean;
135→  borderRadius: string;
136→  customCss: string;
