139→// ── CSS generator — mirrors the Liquid block CSS exactly ────────────────────
140→function buildWidgetCss(wid: string, cfg: WidgetConfig): string {
141→  const rad = cfg.borderRadius + "px";
142→  return (
143→    "#" + wid + "{" +
144→      "background:" + cfg.backgroundColor + ";" +
145→      "color:" + cfg.textColor + ";" +
146→      "border-radius:" + rad + ";" +
147→      "padding:24px;" +
148→      "border:1px solid #e1e3e5;" +
149→      "max-width:400px;" +
150→      "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;" +
151→      "box-sizing:border-box;" +
152→    "}" +
153→    "#" + wid + " *{box-sizing:border-box}" +
154→    "#" + wid + " .zcc-heading{font-size:16px;font-weight:600;margin:0 0 16px;color:" + cfg.textColor + "}" +
155→    "#" + wid + " .zcc-row{display:flex;gap:8px;margin-bottom:0}" +
156→    "#" + wid + " .zcc-input{" +
157→      "flex:1;padding:10px 12px;border:1px solid #c9cccf;" +
158→      "border-radius:" + rad + ";font-size:14px;outline:none;" +
159→      "background:#fafbfb;color:" + cfg.textColor + ";min-width:0" +
160→    "}" +
161→    "#" + wid + " .zcc-input:focus{border-color:" + cfg.primaryColor + ";box-shadow:0 0 0 2px " + cfg.primaryColor + "22}" +
162→    "#" + wid + " .zcc-btn{" +
163→      "background:" + cfg.primaryColor + ";color:#fff;border:none;" +
164→      "border-radius:" + rad + ";padding:10px 20px;font-size:14px;" +
165→      "font-weight:600;cursor:pointer;white-space:nowrap;flex-shrink:0" +
166→    "}" +
167→    "#" + wid + " .zcc-btn:hover{opacity:.9}" +
168→    "#" + wid + " .zcc-result{margin-top:12px;padding:12px;border-radius:" + rad + ";font-size:14px;line-height:1.4}" +
169→    "#" + wid + " .zcc-result.ok{background:" + cfg.successColor + "15;border-left:3px solid " + cfg.successColor + ";color:" + cfg.successColor + "}" +
170→    "#" + wid + " .zcc-result.fail{background:" + cfg.errorColor + "15;border-left:3px solid " + cfg.errorColor + ";color:" + cfg.errorColor + "}" +
171→    "#" + wid + " .zcc-meta{margin-top:4px;font-size:13px;opacity:.8}" +
172→    "#" + wid + " .zcc-wl{margin-top:10px}" +
173→    "#" + wid + " .zcc-wl-input{" +
174→      "width:100%;padding:8px 10px;border:1px solid " + cfg.errorColor + "40;" +
175→      "border-radius:" + rad + ";font-size:13px;margin-bottom:6px;display:block" +
176→    "}" +
177→    "#" + wid + " .zcc-wl-btn{" +
178→      "background:" + cfg.errorColor + ";color:#fff;border:none;" +
179→      "border-radius:" + rad + ";padding:8px 16px;font-size:13px;" +
180→      "cursor:pointer;width:100%;font-weight:600" +
181→    "}" +
182→    (cfg.customCss || "")
183→  );
184→}
