186→// ── Live Preview component (defined outside WidgetPage to avoid remounting) ─
187→function WidgetPreview({
188→  cfg,
189→  previewState,
190→}: {
191→  cfg: WidgetConfig;
192→  previewState: "idle" | "success" | "error" | "notfound";
193→}) {
194→  const wid = "zcc-admin-preview";
195→  const css = buildWidgetCss(wid, cfg);
196→
197→  const resultClass =
198→    previewState === "success" ? "ok" :
199→    (previewState === "error" || previewState === "notfound") ? "fail" : "";
200→
201→  const resultMessage =
202→    previewState === "success" ? cfg.successMessage :
203→    previewState === "error" ? cfg.errorMessage :
204→    previewState === "notfound" ? cfg.notFoundMessage : null;
205→
206→  const widgetHtml = (
207→    <div id={wid}>
208→      <p className="zcc-heading">{cfg.heading}</p>
209→      <div className="zcc-row">
210→        <input
211→          className="zcc-input"
212→          type="text"
213→          placeholder={cfg.placeholder}
214→          readOnly
215→        />
216→        <button className="zcc-btn" type="button">
217→          {cfg.buttonText}
218→        </button>
219→      </div>
220→      {resultMessage && (
221→        <div className={`zcc-result ${resultClass}`}>
222→          {resultMessage}
223→          {previewState === "success" && cfg.showEta && (
224→            <div className="zcc-meta">Estimated delivery: 2–3 business days</div>
225→          )}
226→          {previewState === "success" && cfg.showZone && (
227→            <div className="zcc-meta">Zone: Manhattan</div>
228→          )}
229→          {(previewState === "error" || previewState === "notfound") &&
230→            cfg.showWaitlistOnFailure && (
231→              <div className="zcc-wl">
232→                <input
233→                  className="zcc-wl-input"
234→                  type="email"
235→                  placeholder="Enter email to join waitlist"
236→                  readOnly
237→                />
238→                <button className="zcc-wl-btn" type="button">
239→                  Join Waitlist
240→                </button>
241→              </div>
242→            )}
243→        </div>
244→      )}
245→    </div>
246→  );
247→
248→  // Floating position: show mock fixed button + collapsible panel concept
249→  if (cfg.position === "floating") {
250→    return (
251→      <>
252→        {/* eslint-disable-next-line react/no-danger */}
253→        <style dangerouslySetInnerHTML={{ __html: css }} />
254→        <div
255→          style={{
256→            position: "relative",
257→            minHeight: "120px",
258→            background: "#f6f6f7",
259→            borderRadius: "8px",
260→            padding: "12px",
261→          }}
262→        >
263→          <Text as="p" variant="bodySm" tone="subdued">
264→            The widget will appear as a fixed button in the bottom-right corner of your storefront.
265→          </Text>
266→          <div
267→            style={{
268→              position: "absolute",
269→              bottom: "12px",
270→              right: "12px",
271→              display: "flex",
272→              flexDirection: "column",
273→              alignItems: "flex-end",
274→              gap: "8px",
275→            }}
276→          >
277→            <div id={wid} style={{ maxWidth: "300px" }}>
278→              <p className="zcc-heading" style={{ marginBottom: "12px" }}>
279→                {cfg.heading}
280→              </p>
281→              <div className="zcc-row">
282→                <input
283→                  className="zcc-input"
284→                  type="text"
285→                  placeholder={cfg.placeholder}
286→                  readOnly
287→                />
288→                <button className="zcc-btn" type="button">
289→                  {cfg.buttonText}
290→                </button>
291→              </div>
292→            </div>
293→            <button
294→              type="button"
295→              style={{
296→                background: cfg.primaryColor,
297→                color: "#fff",
298→                border: "none",
299→                borderRadius: "50px",
300→                padding: "10px 18px",
301→                fontSize: "13px",
302→                fontWeight: 600,
303→                cursor: "pointer",
304→                boxShadow: "0 4px 12px rgba(0,0,0,.2)",
305→              }}
306→            >
307→              📍 Check Delivery
308→            </button>
309→          </div>
310→        </div>
311→      </>
312→    );
313→  }
314→
315→  // Popup position: show trigger button + hint of overlay
316→  if (cfg.position === "popup") {
317→    return (
318→      <>
319→        {/* eslint-disable-next-line react/no-danger */}
320→        <style dangerouslySetInnerHTML={{ __html: css }} />
321→        <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
322→          <Text as="p" variant="bodySm" tone="subdued">
323→            A trigger button will appear in the section. Clicking it opens a centered popup.
324→          </Text>
325→          <div>
326→            <button
327→              type="button"
328→              style={{
329→                background: cfg.primaryColor,
330→                color: "#fff",
331→                border: "none",
332→                borderRadius: cfg.borderRadius + "px",
333→                padding: "10px 24px",
334→                fontSize: "14px",
335→                fontWeight: 600,
336→                cursor: "pointer",
337→              }}
338→            >
339→              Check Delivery Availability
340→            </button>
341→          </div>
342→          <div
343→            style={{
344→              background: "rgba(0,0,0,.06)",
345→              borderRadius: "8px",
346→              padding: "12px",
347→              border: "2px dashed #c9cccf",
348→            }}
349→          >
350→            <Text as="p" variant="bodySm" tone="subdued">
351→              Popup content preview:
352→            </Text>
353→            <div style={{ marginTop: "8px" }}>{widgetHtml}</div>
354→          </div>
355→        </div>
356→      </>
357→    );
358→  }
359→
360→  // Inline (default)
361→  return (
362→    <>
363→      {/* eslint-disable-next-line react/no-danger */}
364→      <style dangerouslySetInnerHTML={{ __html: css }} />
365→      {widgetHtml}
366→    </>
367→  );
368→}
