370→// ── Page component ───────────────────────────────────────────────────────────
371→export default function WidgetPage() {
372→  const { config, themeEditorUrl } = useLoaderData<typeof loader>();
373→  const fetcher = useFetcher<typeof action>();
374→  const shopify = useAppBridge();
375→  const navigate = useNavigate();
376→
377→  const c = config as WidgetConfig;
378→
379→  // Form state initialized from DB
380→  const [position, setPosition] = useState(c.position);
381→  const [primaryColor, setPrimaryColor] = useState(c.primaryColor);
382→  const [successColor, setSuccessColor] = useState(c.successColor);
383→  const [errorColor, setErrorColor] = useState(c.errorColor);
384→  const [backgroundColor, setBackgroundColor] = useState(c.backgroundColor);
385→  const [textColor, setTextColor] = useState(c.textColor);
386→  const [heading, setHeading] = useState(c.heading);
387→  const [placeholder, setPlaceholder] = useState(c.placeholder);
388→  const [buttonText, setButtonText] = useState(c.buttonText);
389→  const [successMessage, setSuccessMessage] = useState(c.successMessage);
390→  const [errorMessage, setErrorMessage] = useState(c.errorMessage);
391→  const [notFoundMessage, setNotFoundMessage] = useState(c.notFoundMessage);
392→  const [showEta, setShowEta] = useState(c.showEta);
393→  const [showZone, setShowZone] = useState(c.showZone);
394→  const [showWaitlistOnFailure, setShowWaitlistOnFailure] = useState(
395→    c.showWaitlistOnFailure,
396→  );
397→  const [borderRadius, setBorderRadius] = useState(c.borderRadius);
398→  const [customCss, setCustomCss] = useState(c.customCss || "");
399→
400→  // Unsaved changes tracking
401→  const [isDirty, setIsDirty] = useState(false);
402→
403→  // Preview state
404→  const [previewState, setPreviewState] = useState<
405→    "idle" | "success" | "error" | "notfound"
406→  >("idle");
407→
408→  const isSaving =
409→    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "save";
410→
411→  // Clear dirty flag after successful save
412→  useEffect(() => {
413→    if (
414→      fetcher.state === "idle" &&
415→      fetcher.data &&
416→      "success" in fetcher.data &&
417→      fetcher.data.success
418→    ) {
419→      setIsDirty(false);
420→    }
421→  }, [fetcher.state, fetcher.data]);
422→
423→  // Dirty-aware setters
424→  const mark = useCallback(() => setIsDirty(true), []);
425→  const handlePositionChange = useCallback((v: string) => { setPosition(v); mark(); }, [mark]);
426→  const handlePrimaryColorChange = useCallback((v: string) => { setPrimaryColor(v); mark(); }, [mark]);
427→  const handleSuccessColorChange = useCallback((v: string) => { setSuccessColor(v); mark(); }, [mark]);
428→  const handleErrorColorChange = useCallback((v: string) => { setErrorColor(v); mark(); }, [mark]);
429→  const handleBackgroundColorChange = useCallback((v: string) => { setBackgroundColor(v); mark(); }, [mark]);
430→  const handleTextColorChange = useCallback((v: string) => { setTextColor(v); mark(); }, [mark]);
431→  const handleHeadingChange = useCallback((v: string) => { setHeading(v); mark(); }, [mark]);
432→  const handlePlaceholderChange = useCallback((v: string) => { setPlaceholder(v); mark(); }, [mark]);
433→  const handleButtonTextChange = useCallback((v: string) => { setButtonText(v); mark(); }, [mark]);
434→  const handleSuccessMessageChange = useCallback((v: string) => { setSuccessMessage(v); mark(); }, [mark]);
435→  const handleErrorMessageChange = useCallback((v: string) => { setErrorMessage(v); mark(); }, [mark]);
436→  const handleNotFoundMessageChange = useCallback((v: string) => { setNotFoundMessage(v); mark(); }, [mark]);
437→  const handleShowEtaChange = useCallback((v: boolean) => { setShowEta(v); mark(); }, [mark]);
438→  const handleShowZoneChange = useCallback((v: boolean) => { setShowZone(v); mark(); }, [mark]);
439→  const handleShowWaitlistChange = useCallback((v: boolean) => { setShowWaitlistOnFailure(v); mark(); }, [mark]);
440→  const handleBorderRadiusChange = useCallback((v: string) => { setBorderRadius(v); mark(); }, [mark]);
441→  const handleCustomCssChange = useCallback((v: string) => { setCustomCss(v); mark(); }, [mark]);
442→
443→  const handleSave = useCallback(() => {
444→    const fd = new FormData();
445→    fd.set("intent", "save");
446→    fd.set("position", position);
447→    fd.set("primaryColor", primaryColor);
448→    fd.set("successColor", successColor);
449→    fd.set("errorColor", errorColor);
450→    fd.set("backgroundColor", backgroundColor);
451→    fd.set("textColor", textColor);
452→    fd.set("heading", heading);
453→    fd.set("placeholder", placeholder);
454→    fd.set("buttonText", buttonText);
455→    fd.set("successMessage", successMessage);
456→    fd.set("errorMessage", errorMessage);
457→    fd.set("notFoundMessage", notFoundMessage);
458→    fd.set("showEta", String(showEta));
459→    fd.set("showZone", String(showZone));
460→    fd.set("showWaitlistOnFailure", String(showWaitlistOnFailure));
461→    fd.set("borderRadius", borderRadius);
462→    fd.set("customCss", customCss);
463→    fetcher.submit(fd, { method: "POST" });
464→    shopify.toast.show("Widget settings saved");
465→  }, [
466→    position, primaryColor, successColor, errorColor, backgroundColor,
467→    textColor, heading, placeholder, buttonText, successMessage, errorMessage,
468→    notFoundMessage, showEta, showZone, showWaitlistOnFailure, borderRadius,
469→    customCss, fetcher, shopify,
470→  ]);
471→
472→  const DEFAULTS = {
473→    position: "inline",
474→    primaryColor: "#008060",
475→    successColor: "#008060",
476→    errorColor: "#D72C0D",
477→    backgroundColor: "#FFFFFF",
478→    textColor: "#202223",
479→    heading: "Check Delivery Availability",
480→    placeholder: "Enter your zip code",
481→    buttonText: "Check",
482→    successMessage: "Great news! We deliver to your area.",
483→    errorMessage: "Sorry, we don't deliver to this area yet.",
484→    notFoundMessage: "This zip code was not found in our system.",
485→    showEta: true,
486→    showZone: false,
487→    showWaitlistOnFailure: false,
488→    borderRadius: "8",
489→    customCss: "",
490→  };
491→
492→  const handleReset = useCallback(() => {
493→    const fd = new FormData();
494→    fd.set("intent", "reset");
495→    fetcher.submit(fd, { method: "POST" });
496→    setPosition(DEFAULTS.position);
497→    setPrimaryColor(DEFAULTS.primaryColor);
498→    setSuccessColor(DEFAULTS.successColor);
499→    setErrorColor(DEFAULTS.errorColor);
500→    setBackgroundColor(DEFAULTS.backgroundColor);
501→    setTextColor(DEFAULTS.textColor);
502→    setHeading(DEFAULTS.heading);
503→    setPlaceholder(DEFAULTS.placeholder);
504→    setButtonText(DEFAULTS.buttonText);
505→    setSuccessMessage(DEFAULTS.successMessage);
506→    setErrorMessage(DEFAULTS.errorMessage);
507→    setNotFoundMessage(DEFAULTS.notFoundMessage);
508→    setShowEta(DEFAULTS.showEta);
509→    setShowZone(DEFAULTS.showZone);
510→    setShowWaitlistOnFailure(DEFAULTS.showWaitlistOnFailure);
511→    setBorderRadius(DEFAULTS.borderRadius);
512→    setCustomCss(DEFAULTS.customCss);
513→    setPreviewState("idle");
514→    setIsDirty(false);
515→    shopify.toast.show("Widget settings reset to defaults");
516→  // eslint-disable-next-line react-hooks/exhaustive-deps
517→  }, [fetcher, shopify]);
518→
519→  const positionOptions = [
520→    { label: "Inline — embedded directly in the section", value: "inline" },
521→    { label: "Floating — fixed button in the corner", value: "floating" },
522→    { label: "Popup — trigger button opens a modal", value: "popup" },
523→  ];
524→
525→  // Current config snapshot for the preview
526→  const previewCfg: WidgetConfig = {
527→    position, primaryColor, successColor, errorColor, backgroundColor,
528→    textColor, heading, placeholder, buttonText, successMessage, errorMessage,
529→    notFoundMessage, showEta, showZone, showWaitlistOnFailure, borderRadius,
530→    customCss,
531→  };
532→
533→  return (
534→    <Page
535→      title="Widget Customization"
536→      subtitle="Customize how the zip code checker looks on your storefront"
537→      backAction={{ onAction: () => navigate("/app") }}
538→      primaryAction={{
539→        content: "Save Changes",
540→        onAction: handleSave,
541→        loading: isSaving,
542→      }}
543→      secondaryActions={[
544→        {
545→          content: "Reset to Defaults",
546→          onAction: handleReset,
547→        },
548→      ]}
549→    >
550→      <Box paddingBlockEnd="1600">
551→        <Layout>
552→          {/* Unsaved changes warning */}
553→          {isDirty && !isSaving && (
554→            <Layout.Section>
555→              <Banner tone="warning" title="You have unsaved changes">
556→                <Text as="p" variant="bodySm">
557→                  Click <strong>Save Changes</strong> to apply your updates to the storefront.
558→                </Text>
559→              </Banner>
560→            </Layout.Section>
561→          )}
562→
563→          {/* How to enable card */}
564→          <Layout.Section>
565→            <Card>
566→              <BlockStack gap="400">
567→                <BlockStack gap="100">
568→                  <Text as="h2" variant="headingMd">
569→                    Add widget to your storefront
570→                  </Text>
571→                  <Text as="p" variant="bodySm" tone="subdued">
572→                    Follow these steps to display the zip code checker on your
573→                    online store. No manual URL configuration required.
574→                  </Text>
575→                </BlockStack>
576→                <Divider />
577→                <BlockStack gap="300">
578→                  <Text as="p" variant="bodyMd">
579→                    <strong>Step 1 —</strong> Save your widget settings using the{" "}
580→                    <strong>Save Changes</strong> button above
581→                  </Text>
