  1→{% comment %}
  2→  Zip Code Checker — Theme App Extension Block
  3→  Add this block to any section in the Shopify Theme Editor.
  4→  The block automatically connects to your app — no manual configuration needed.
  5→{% endcomment %}
  6→
  7→<div
  8→  id="zcc-widget-{{ block.id }}"
  9→  data-shop="{{ shop.permanent_domain }}"
 10→  data-api="{{ app.url }}"
 11→  data-block="{{ block.id }}"
 12→  {{ block.shopify_attributes }}
 13→></div>
 14→
 15→<script>
 16→(function () {
 17→  var ROOT_ID = "zcc-widget-{{ block.id }}";
 18→  var container = document.getElementById(ROOT_ID);
 19→  if (!container) return;
 20→
 21→  var SHOP = container.dataset.shop;
 22→  var API_BASE = (container.dataset.api || "").replace(/\/$/, "");
 23→
 24→  // Fetch widget config, then render
 25→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
 26→    .then(function (r) { return r.json(); })
 27→    .then(function (cfg) { renderWidget(cfg); })
 28→    .catch(function () { renderWidget({}); });
 29→
 30→  function renderWidget(cfg) {
 31→    // Merge with defaults
 32→    var D = {
 33→      position: "inline",
 34→      heading: "Check Delivery Availability",
 35→      placeholder: "Enter your zip code",
 36→      buttonText: "Check",
 37→      successMessage: "Great news! We deliver to your area.",
 38→      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
 39→      notFoundMessage: "This zip code was not found in our system.",
 40→      primaryColor: "#008060",
 41→      successColor: "#008060",
 42→      errorColor: "#D72C0D",
 43→      backgroundColor: "#FFFFFF",
 44→      textColor: "#202223",
 45→      borderRadius: "8",
 46→      showEta: true,
 47→      showZone: false,
 48→      showWaitlistOnFailure: false,
 49→      customCss: "",
 50→    };
 51→    Object.keys(D).forEach(function (k) {
 52→      if (cfg[k] === undefined || cfg[k] === null || cfg[k] === "") cfg[k] = D[k];
 53→    });
 54→
 55→    var rad = cfg.borderRadius + "px";
 56→    var WID = "zcc-" + ROOT_ID;
 57→
 58→    if (cfg.position === "floating") {
 59→      renderFloating(cfg, WID, rad);
 60→    } else if (cfg.position === "popup") {
 61→      renderPopup(cfg, WID, rad);
 62→    } else {
 63→      renderInline(cfg, WID, rad);
 64→    }
 65→  }
 66→
 67→  // ── Shared: inject CSS ──────────────────────────────────────────────────────
 68→  function injectCss(wid, cfg, rad) {
 69→    var css =
 70→      "#" + wid + "{" +
 71→        "background:" + cfg.backgroundColor + ";" +
 72→        "color:" + cfg.textColor + ";" +
 73→        "border-radius:" + rad + ";" +
 74→        "padding:24px;" +
 75→        "border:1px solid #e1e3e5;" +
 76→        "max-width:480px;" +
 77→        "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;" +
 78→        "box-sizing:border-box;" +
 79→      "}" +
 80→      "#" + wid + " *{box-sizing:border-box}" +
 81→      "#" + wid + " .zcc-heading{font-size:16px;font-weight:600;margin:0 0 16px;color:" + cfg.textColor + "}" +
 82→      "#" + wid + " .zcc-row{display:flex;gap:8px;margin-bottom:0}" +
 83→      "#" + wid + " .zcc-input{" +
 84→        "flex:1;padding:10px 12px;border:1px solid #c9cccf;" +
 85→        "border-radius:" + rad + ";font-size:14px;outline:none;" +
 86→        "background:#fafbfb;color:" + cfg.textColor + ";min-width:0" +
 87→      "}" +
 88→      "#" + wid + " .zcc-input:focus{border-color:" + cfg.primaryColor + ";box-shadow:0 0 0 2px " + cfg.primaryColor + "22}" +
 89→      "#" + wid + " .zcc-btn{" +
 90→        "background:" + cfg.primaryColor + ";color:#fff;border:none;" +
 91→        "border-radius:" + rad + ";padding:10px 20px;font-size:14px;" +
 92→        "font-weight:600;cursor:pointer;white-space:nowrap;flex-shrink:0" +
 93→      "}" +
 94→      "#" + wid + " .zcc-btn:hover{opacity:.9}" +
 95→      "#" + wid + " .zcc-btn:disabled{opacity:.6;cursor:not-allowed}" +
 96→      "#" + wid + " .zcc-result{margin-top:12px;padding:12px;border-radius:" + rad + ";font-size:14px;line-height:1.4}" +
 97→      "#" + wid + " .zcc-result.ok{background:" + cfg.successColor + "15;border-left:3px solid " + cfg.successColor + ";color:" + cfg.successColor + "}" +
 98→      "#" + wid + " .zcc-result.fail{background:" + cfg.errorColor + "15;border-left:3px solid " + cfg.errorColor + ";color:" + cfg.errorColor + "}" +
 99→      "#" + wid + " .zcc-meta{margin-top:4px;font-size:13px;opacity:.8}" +
100→      "#" + wid + " .zcc-wl{margin-top:10px}" +
101→      "#" + wid + " .zcc-wl-input{" +
102→        "width:100%;padding:8px 10px;border:1px solid " + cfg.errorColor + "40;" +
103→        "border-radius:" + rad + ";font-size:13px;margin-bottom:6px;display:block" +
104→      "}" +
105→      "#" + wid + " .zcc-wl-btn{" +
106→        "background:" + cfg.errorColor + ";color:#fff;border:none;" +
107→        "border-radius:" + rad + ";padding:8px 16px;font-size:13px;" +
108→        "cursor:pointer;width:100%;font-weight:600" +
109→      "}" +
110→      "#" + wid + " .zcc-wl-btn:disabled{opacity:.6;cursor:not-allowed}" +
111→      (cfg.customCss || "");
112→
113→    var styleEl = document.createElement("style");
114→    styleEl.textContent = css;
115→    document.head.appendChild(styleEl);
116→  }
