118→  // ── Shared: build widget inner HTML + wire up events ────────────────────────
119→  function buildWidgetInner(wid, cfg, btnLabel) {
120→    return (
121→      '<p class="zcc-heading">' + esc(cfg.heading) + "</p>" +
122→      '<div class="zcc-row">' +
123→        '<input class="zcc-input" type="text" id="' + wid + '-inp"' +
124→          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
125→          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
126→        '<button class="zcc-btn" id="' + wid + '-btn" type="button">' + esc(btnLabel) + "</button>" +
127→      "</div>" +
128→      '<div id="' + wid + '-res"></div>'
129→    );
130→  }
131→
132→  function wireWidget(wid, cfg, API_BASE, SHOP) {
133→    var inp = document.getElementById(wid + "-inp");
134→    var btn = document.getElementById(wid + "-btn");
135→    var res = document.getElementById(wid + "-res");
136→    var btnLabel = cfg.buttonText;
137→    if (!inp || !btn || !res) return;
138→
139→    function checkZip() {
140→      var zip = inp.value.trim();
141→      if (!zip) { inp.focus(); return; }
142→
143→      btn.disabled = true;
144→      btn.textContent = "\u2026";
145→      res.innerHTML = "";
146→
147→      fetch(
148→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
149→          "&zip=" + encodeURIComponent(zip)
150→      )
151→        .then(function (r) { return r.json(); })
152→        .then(function (data) {
153→          btn.disabled = false;
154→          btn.textContent = btnLabel;
155→
156→          if (data.allowed) {
157→            var html = '<div class="zcc-result ok">' + esc(data.message);
158→            if (cfg.showEta && data.eta) {
159→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
160→            }
161→            if (cfg.showZone && data.zone) {
162→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
163→            }
164→            html += "</div>";
165→            res.innerHTML = html;
166→          } else {
167→            var html = '<div class="zcc-result fail">' + esc(data.message);
168→            if (cfg.showWaitlistOnFailure) {
169→              html +=
170→                '<div class="zcc-wl">' +
171→                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Enter email to join waitlist" />' +
172→                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button">Join Waitlist</button>' +
173→                "</div>";
174→            }
175→            html += "</div>";
176→            res.innerHTML = html;
177→
178→            if (cfg.showWaitlistOnFailure) {
179→              var wBtn = document.getElementById(wid + "-wl-btn");
180→              if (wBtn) {
181→                wBtn.addEventListener("click", function () {
182→                  var emailEl = document.getElementById(wid + "-wl-email");
183→                  var email = emailEl ? emailEl.value.trim() : "";
184→                  if (!email) { if (emailEl) emailEl.focus(); return; }
185→                  joinWaitlist(zip, email, wBtn);
186→                });
187→              }
188→            }
189→          }
190→        })
191→        .catch(function () {
192→          btn.disabled = false;
193→          btn.textContent = btnLabel;
194→          res.innerHTML = '<div class="zcc-result fail">Something went wrong. Please try again.</div>';
195→        });
196→    }
197→
198→    btn.addEventListener("click", checkZip);
199→    inp.addEventListener("keydown", function (e) {
200→      if (e.key === "Enter") checkZip();
201→    });
202→  }
203→
204→  function joinWaitlist(zip, email, wBtn) {
205→    wBtn.disabled = true;
206→    wBtn.textContent = "Joining\u2026";
207→
208→    fetch(API_BASE + "/api/waitlist", {
209→      method: "POST",
210→      headers: { "Content-Type": "application/json" },
211→      body: JSON.stringify({ shop: SHOP, zip: zip, email: email }),
212→    })
213→      .then(function (r) { return r.json(); })
214→      .then(function (data) {
215→        var wlEl = wBtn.closest(".zcc-wl");
216→        if (data.success) {
217→          if (wlEl) wlEl.innerHTML =
218→            '<p style="font-size:13px;margin:6px 0 0">' +
219→            "\u2713 You\u2019ve been added to the waitlist!" +
220→            "</p>";
221→        } else {
222→          wBtn.disabled = false;
223→          wBtn.textContent = "Join Waitlist";
224→        }
225→      })
226→      .catch(function () {
227→        wBtn.disabled = false;
228→        wBtn.textContent = "Join Waitlist";
229→      });
230→  }
