240→  // ── Floating position ────────────────────────────────────────────────────────
241→  function renderFloating(cfg, WID, rad) {
242→    // The original container becomes invisible (just an anchor)
243→    container.style.display = "none";
244→
245→    injectCss(WID, cfg, rad);
246→
247→    // Additional styles for floating UI
248→    var floatCss =
249→      "#" + WID + "-float{position:fixed;bottom:20px;right:20px;z-index:9998;display:flex;flex-direction:column;align-items:flex-end;gap:10px}" +
250→      "#" + WID + "-panel{" +
251→        "background:" + cfg.backgroundColor + ";border-radius:" + rad + ";" +
252→        "box-shadow:0 8px 32px rgba(0,0,0,.18);overflow:hidden;" +
253→        "transition:opacity .2s,transform .2s;transform-origin:bottom right" +
254→      "}" +
255→      "#" + WID + "-panel.zcc-hidden{display:none}" +
256→      "#" + WID + "-panel .zcc-panel-header{" +
257→        "display:flex;align-items:center;justify-content:space-between;" +
258→        "padding:14px 16px 0;margin-bottom:0" +
259→      "}" +
260→      "#" + WID + "-panel .zcc-panel-close{" +
261→        "background:none;border:none;cursor:pointer;font-size:20px;line-height:1;" +
262→        "color:" + cfg.textColor + ";opacity:.6;padding:0 4px" +
263→      "}" +
264→      "#" + WID + "-panel .zcc-panel-close:hover{opacity:1}" +
265→      "#" + WID + "-trigger{" +
266→        "background:" + cfg.primaryColor + ";color:#fff;border:none;" +
267→        "border-radius:50px;padding:12px 20px;font-size:14px;font-weight:600;" +
268→        "cursor:pointer;box-shadow:0 4px 12px rgba(0,0,0,.2);white-space:nowrap" +
269→      "}" +
270→      "#" + WID + "-trigger:hover{opacity:.9}";
271→
272→    var floatStyle = document.createElement("style");
273→    floatStyle.textContent = floatCss;
274→    document.head.appendChild(floatStyle);
275→
276→    // Build floating shell
277→    var floatEl = document.createElement("div");
278→    floatEl.id = WID + "-float";
279→    floatEl.innerHTML =
280→      '<div id="' + WID + '-panel" class="zcc-hidden">' +
281→        '<div class="zcc-panel-header">' +
282→          '<span style="font-size:13px;font-weight:600;color:' + cfg.textColor + '">Delivery Check</span>' +
283→          '<button class="zcc-panel-close" id="' + WID + '-close" type="button" aria-label="Close">&times;</button>' +
284→        '</div>' +
285→        '<div id="' + WID + '">' +
286→          buildWidgetInner(WID, cfg, cfg.buttonText) +
287→        '</div>' +
288→      '</div>' +
289→      '<button id="' + WID + '-trigger" type="button">' +
290→        '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="vertical-align:middle;margin-right:6px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
291→        esc(cfg.buttonText || "Check Delivery") +
292→      '</button>';
293→
294→    document.body.appendChild(floatEl);
295→
296→    // Wire toggle
297→    var trigger = document.getElementById(WID + "-trigger");
298→    var panel = document.getElementById(WID + "-panel");
299→    var closeBtn = document.getElementById(WID + "-close");
300→
301→    if (trigger && panel) {
302→      trigger.addEventListener("click", function () {
303→        panel.classList.toggle("zcc-hidden");
304→      });
305→    }
306→    if (closeBtn && panel) {
307→      closeBtn.addEventListener("click", function () {
308→        panel.classList.add("zcc-hidden");
309→      });
310→    }
311→    // Close on outside click
312→    document.addEventListener("click", function (e) {
313→      if (!floatEl.contains(e.target)) {
314→        if (panel) panel.classList.add("zcc-hidden");
315→      }
316→    });
317→
318→    wireWidget(WID, cfg, API_BASE, SHOP);
319→  }
