321→  // ── Popup position ───────────────────────────────────────────────────────────
322→  function renderPopup(cfg, WID, rad) {
323→    injectCss(WID, cfg, rad);
324→
325→    var popupCss =
326→      "#" + WID + "-overlay{" +
327→        "display:none;position:fixed;inset:0;background:rgba(0,0,0,.55);" +
328→        "z-index:9999;align-items:center;justify-content:center;padding:16px" +
329→      "}" +
330→      "#" + WID + "-overlay.zcc-open{display:flex}" +
331→      "#" + WID + "-modal{" +
332→        "background:" + cfg.backgroundColor + ";border-radius:" + rad + ";" +
333→        "max-width:480px;width:100%;position:relative;" +
334→        "box-shadow:0 20px 60px rgba(0,0,0,.3)" +
335→      "}" +
336→      "#" + WID + "-modal .zcc-modal-close{" +
337→        "position:absolute;top:10px;right:14px;background:none;border:none;" +
338→        "font-size:22px;line-height:1;cursor:pointer;color:" + cfg.textColor + ";opacity:.5" +
339→      "}" +
340→      "#" + WID + "-modal .zcc-modal-close:hover{opacity:1}" +
341→      "#" + WID + "-popup-trigger{" +
342→        "background:" + cfg.primaryColor + ";color:#fff;border:none;" +
343→        "border-radius:" + rad + ";padding:10px 24px;font-size:14px;font-weight:600;" +
344→        "cursor:pointer" +
345→      "}" +
346→      "#" + WID + "-popup-trigger:hover{opacity:.9}";
347→
348→    var popupStyle = document.createElement("style");
349→    popupStyle.textContent = popupCss;
350→    document.head.appendChild(popupStyle);
351→
352→    // Trigger button renders in-place (inside the block)
353→    container.innerHTML =
354→      '<button id="' + WID + '-popup-trigger" type="button">' +
355→        esc(cfg.heading) +
356→      '</button>';
357→
358→    // Overlay + modal append to body
359→    var overlay = document.createElement("div");
360→    overlay.id = WID + "-overlay";
361→    overlay.innerHTML =
362→      '<div id="' + WID + '-modal">' +
363→        '<button class="zcc-modal-close" id="' + WID + '-modal-close" type="button" aria-label="Close">&times;</button>' +
364→        '<div id="' + WID + '">' +
365→          buildWidgetInner(WID, cfg, cfg.buttonText) +
366→        '</div>' +
367→      '</div>';
368→    document.body.appendChild(overlay);
369→
370→    var trigger = document.getElementById(WID + "-popup-trigger");
371→    var closeBtn = document.getElementById(WID + "-modal-close");
372→    var modal = document.getElementById(WID + "-modal");
373→
374→    function openPopup() { overlay.classList.add("zcc-open"); }
375→    function closePopup() { overlay.classList.remove("zcc-open"); }
376→
377→    if (trigger) trigger.addEventListener("click", openPopup);
378→    if (closeBtn) closeBtn.addEventListener("click", closePopup);
379→
380→    // Close on overlay backdrop click (not modal content)
381→    overlay.addEventListener("click", function (e) {
382→      if (e.target === overlay) closePopup();
383→    });
384→
385→    // Close on Escape key
386→    document.addEventListener("keydown", function (e) {
387→      if (e.key === "Escape") closePopup();
388→    });
389→
390→    wireWidget(WID, cfg, API_BASE, SHOP);
391→  }
