393→  function esc(str) {
394→    return String(str)
395→      .replace(/&/g, "&amp;")
396→      .replace(/</g, "&lt;")
397→      .replace(/>/g, "&gt;")
398→      .replace(/"/g, "&quot;");
399→  }
400→
401→  function escAttr(str) {
402→    return String(str).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
403→  }
404→})();
